H('38.d.2.B',3,"Overgrazed range often leads to:","poorer water quality from runoff",["cleaner streams","more infiltration","less erosion"],"Bare soil erodes.")
H('38.d.2.C',3,"A limitation of rangeland is that it often has:","low rainfall and poor soils for crops",["perfect soils","plentiful water","flat fields only"],"Range suits grazing, not tillage.")
H('38.d.2.C',3,"Rangelands are best suited for:","grazing and wildlife",["rice farming","vegetable gardens","orchards"],"Capability determines use.")
H('38.d.3.A',3,"Rangeland relates to the environment by providing:","wildlife habitat and watershed protection",["only noise","only roads","only heat"],"Range supports ecosystems.")
H('38.d.3.A',3,"Native grasslands provide:","forage and habitat",["pavement","buildings","parking"],"They are productive ecosystems.")
H('38.d.3.B',4,"Carrying capacity on a ranch is the:","number of animals the land can support",["number of fences","size of the herd on paper","length of the lease"],"It limits stocking.")
H('38.d.3.B',4,"Stocking too many cattle may cause:","overgrazing",["more forage","healthier plants","better soil"],"Exceeding capacity harms range.")
H('38.d.3.C',3,"An invasive plant is one that:","spreads aggressively and harms native systems",["is always welcome","is native","grows only in pots"],"Invasives outcompete natives.")
H('38.d.3.C',3,"A native range grass is:","little bluestem",["kudzu","saltcedar","giant reed"],"Little bluestem is native to Texas prairies.")
H('38.d.3.D',3,"Switchgrass is studied as a source of:","biofuel",["lumber","food coloring","glass"],"Grasses can produce ethanol.")
H('38.d.3.D',3,"Using rangeland plants for energy requires:","balancing production with conservation",["clearing all land","ignoring wildlife","stopping grazing forever"],"Sustainable use matters.")
H('38.d.3.E',3,"Rangeland helps recharge aquifers by:","letting rainwater soak into the ground",["sealing the soil","blocking water","raising runoff"],"Healthy cover increases infiltration.")
H('38.d.3.E',3,"Conserving water on range can include:","building water-spreading structures",["draining ponds","paving","overgrazing"],"Structures slow runoff.")
H('38.d.3.F',3,"Successful range practices help to:","keep land productive for the future",["ruin the land","end grazing","remove plants"],"Sustainability is the goal.")
H('38.d.3.F',3,"Rotational grazing benefits range by:","giving plants time to recover",["stressing plants","eliminating cover","speeding erosion"],"Rest periods restore plants.")
H('38.d.4.A',3,"Soil is an important rangeland component because it:","supplies water and nutrients to plants",["blocks growth","holds no water","repels roots"],"Soil supports forage.")
H('38.d.4.A',3,"Deep soils on range generally:","hold more water for plants",["hold less water","support fewer plants","produce less forage"],"Depth increases storage.")
H('38.d.4.B',3,"Topography affects range by influencing:","drainage and sun exposure",["the color of cattle","the price of beef","grazing licenses"],"Slope and aspect matter.")
H('38.d.4.B',3,"South-facing slopes in Texas are generally:","warmer and drier",["colder and wetter","underwater","shaded all day"],"Sun exposure dries soil.")
H('38.d.4.C',3,"A range site is a unit of land that:","has similar soils and produces similar plants",["has the same owner","has the same fence","has the same road"],"Sites are classified by soil.")
H('38.d.4.C',3,"Classifying range sites helps managers to:","predict forage production",["pick cattle breeds","set prices","plan holidays"],"Sites guide stocking rates.")
