H('38.d.5.C',3,"A method to improve range condition is:","adjusting stocking rates",["overgrazing","ignoring weeds","plowing"],"Matching animals to forage helps.")
H('38.d.5.C',3,"Brush management may improve range by:","increasing grass production",["killing all grass","adding more brush","removing water"],"Reducing brush frees moisture.")
H('38.d.6.A',3,"A plant beneficial to livestock is:","bermudagrass",["poison hemlock","locoweed","oleander"],"Bermudagrass is a good forage.")
