H('38.d.8.B',3,"Range vegetation affects the environment by:","reducing erosion and storing carbon",["increasing dust","removing habitat","drying streams"],"Plants protect land.")
H('38.d.8.B',3,"Bare, overgrazed range increases:","dust and runoff",["rainfall","grass","wildlife"],"Bare ground erodes.")
H('38.d.8.C',3,"Good range management benefits the environment through:","maintaining plant cover and soil health",["stripping land","burning always","plowing slopes"],"Management protects resources.")
H('38.d.8.C',3,"Prescribed burning on range can:","control brush and renew grass",["destroy everything","increase brush","stop growth forever"],"Fire is a management tool.")
H('38.d.8.D',4,"Wind farms and oil pads on rangeland can affect it by:","disturbing soil and habitat",["improving every site","having no impact","adding rainfall"],"Energy development has impacts.")
H('38.d.8.D',4,"Reclamation after energy development involves:","restoring soil and replanting native plants",["leaving bare ground","paving the site","abandoning pits"],"Restoring land reduces harm.")

